function call(fn: (...a: any[]) => any, x: any): any { return fn(x); }
function wrap(fn: (...a: any[]) => any): any {
  return function (...a: any[]) { return fn(...a); };
}
function succeed(fn: (...a: any[]) => any): any {
  return wrap(function (err: any, ...args: any[]) { return fn(...args); });
}
function main(): void {
  console.log(call(function (err: any, ...rest: any[]) { return err + ':' + rest.length; }, 5));
  console.log(call((err: any, ...rest: any[]) => err + ':' + rest.length, 6));
  const cb = succeed((x: number, y: number) => x + y);
  console.log(cb(null, 3, 4));
  const cb2 = wrap((e: any, a: any, ...r: any[]) => e + '|' + a + '|' + r.join(','));
  console.log(cb2('e', 'a', 1, 2, 3));
}
